-- Vídeos e nichos do portfólio, migrados do array fixo que vivia em
-- index.html pra cá. Dali em diante o site público busca essa lista aqui
-- (só leitura, só o que estiver visivel=true) e o painel edita ao vivo
-- (arrastar ordem, ocultar, excluir, adicionar) sem precisar publicar de
-- novo o index.html.

create table if not exists portfolio_nichos (
  id uuid primary key default gen_random_uuid(),
  nome text not null,
  cor text,
  horizontal boolean not null default false,
  ordem int not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists portfolio_videos (
  id uuid primary key default gen_random_uuid(),
  nicho_id uuid not null references portfolio_nichos(id) on delete cascade,
  marca text not null,
  conteudo text,
  capa text,
  link text not null,
  gradiente text,
  visivel boolean not null default true,
  ordem int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_portfolio_videos_nicho on portfolio_videos(nicho_id);

alter table portfolio_nichos enable row level security;
alter table portfolio_videos enable row level security;

-- painel (autenticado): acesso completo, igual ao resto do painel
-- (drop if exists antes de cada create, pra esse arquivo poder rodar de novo
-- sem travar em "policy already exists" caso uma tentativa anterior tenha
-- parado no meio do caminho)
drop policy if exists "autenticados podem tudo em portfolio_nichos" on portfolio_nichos;
create policy "autenticados podem tudo em portfolio_nichos" on portfolio_nichos for all to authenticated using (true) with check (true);
drop policy if exists "autenticados podem tudo em portfolio_videos" on portfolio_videos;
create policy "autenticados podem tudo em portfolio_videos" on portfolio_videos for all to authenticated using (true) with check (true);

-- site público (chave anônima, sem login): só leitura, e só do que está visível
drop policy if exists "leitura publica de portfolio_nichos" on portfolio_nichos;
create policy "leitura publica de portfolio_nichos" on portfolio_nichos for select to anon using (true);
drop policy if exists "leitura publica de portfolio_videos_visiveis" on portfolio_videos;
create policy "leitura publica de portfolio_videos_visiveis" on portfolio_videos for select to anon using (visivel = true);

-- ---------------------------------------------------------------------
-- Dados atuais (migrados do array "conteudo.nichos" do index.html)
-- ---------------------------------------------------------------------
on conflict (id) do nothing;

on conflict (id) do nothing;

